// School Academy Cash Receipt Voucher - exact design from iqra_academy_receipt_voucher.html
const LOGO = 'data:image/png;base64,';

const TEMPLATE = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>School Academy — Cash Receipt Voucher</title>
<style>
  :root{
    --maroon: #6E2138;
    --maroon-dark: #4A1626;
    --purple: #6B3FA0;
    --green: #1F7A4D;
    --ring-red: #C0392B;
    --gold: #F0BE3D;
    --orange: #E07C1E;
    --stamp-red: #A63A2E;
    --paper: #F2E7CE;
    --paper-light: #FAF3E2;
    --ink: #2B2118;
    --ink-soft: #5B4C3B;
    --hairline: #C6AD82;

    --font-display: Georgia, 'Iowan Old Style', 'Times New Roman', serif;
    --font-label: 'Helvetica Neue', Arial, sans-serif;
    --font-mono: 'Courier New', Courier, monospace;
  }

  *{ box-sizing: border-box; }

  body{
    margin:0;
    min-height:100vh;
    background:
      repeating-linear-gradient(90deg, rgba(255,255,255,0.015) 0px, rgba(255,255,255,0.015) 1px, transparent 1px, transparent 3px),
      linear-gradient(160deg, #2E2016 0%, #3B2A1D 55%, #2A1D14 100%);
    display:flex;
    flex-direction:column;
    align-items:center;
    padding: 36px 16px 60px;
    font-family: var(--font-label);
    color: var(--ink);
  }

  .toolbar{
    width:100%;
    max-width: 960px;
    display:flex;
    justify-content:flex-end;
    margin-bottom: 14px;
  }

  .toolbar button{
    font-family: var(--font-label);
    font-size: 13px;
    letter-spacing: .04em;
    text-transform: uppercase;
    background: var(--orange);
    color: #2A1B06;
    border: none;
    padding: 9px 18px;
    border-radius: 3px;
    cursor: pointer;
    font-weight: 700;
    box-shadow: 0 2px 0 rgba(0,0,0,0.25);
  }
  .toolbar button:hover{ filter: brightness(1.06); }
  .toolbar button:active{ transform: translateY(1px); box-shadow: 0 1px 0 rgba(0,0,0,0.25); }
  .toolbar button:focus-visible{ outline: 2px solid #fff; outline-offset: 2px; }

  .voucher{
    position: relative;
    width: 100%;
    max-width: 960px;
    background: var(--paper);
    box-shadow: 0 18px 40px rgba(0,0,0,0.45), 0 2px 0 rgba(0,0,0,0.1);
    border-radius: 2px;
  }

  /* signature element: torn perforation stub, echoing the receipt booklet edge */
  .perforation{
    position:absolute;
    left:0; top:0; bottom:0;
    width: 20px;
    background: var(--paper);
    border-right: 2px dashed rgba(43,33,24,0.28);
  }
  .perforation::before{
    content:"";
    position:absolute;
    left: 6px; top:0; bottom:0;
    width:1px;
    background-image: radial-gradient(circle, rgba(43,33,24,0.35) 2.4px, transparent 2.5px);
    background-size: 100% 24px;
    background-repeat: repeat-y;
  }

  .voucher-inner{
    padding: 26px 30px 24px 46px;
  }

  /* ---- header: brand badge | identity | title & meta ---- */
  header.head{
    display:grid;
    grid-template-columns: auto 1fr auto;
    align-items:center;
    gap: 22px;
  }

  .brand{
    display:flex;
    align-items:center;
    gap: 12px;
  }

  .badge-wrap{
    position:relative;
    width: 78px;
    height: 78px;
    flex: none;
  }
  .badge-wrap::before{
    content:"";
    position:absolute;
    inset:0;
    border-radius:50%;
    background: conic-gradient(from 0deg, var(--gold), var(--orange), var(--ring-red), var(--orange), var(--gold));
  }
  .badge{
    position:absolute;
    inset: 5px;
    border-radius:50%;
    background: var(--paper-light);
    border: 3px solid var(--paper);
    display:flex;
    align-items:center;
    justify-content:center;
    overflow:hidden;
  }
  .badge img{ width: 76%; height:76%; object-fit:contain; }

  .wordmark{ display:flex; flex-direction:column; line-height:1.05; }
  .wordmark .iqra{
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 24px;
    color: var(--maroon);
    letter-spacing: .01em;
  }
  .wordmark .academy{
    font-weight: 700;
    font-size: 10.5px;
    letter-spacing: .22em;
    text-transform: uppercase;
    color: var(--purple);
    margin-top: 2px;
  }

  .identity{ text-align:center; }
  .identity p{ margin: 0 0 2px; }

  .identity .so{
    font-family: var(--font-display);
    font-style: italic;
    font-weight: 700;
    font-size: 12.5px;
    color: var(--maroon-dark);
  }
  .identity .am{ font-weight: 700; font-size: 12.5px; color: var(--ink); }
  .identity .en-name{
    font-family: var(--font-display);
    font-weight: 700;
    font-size: 13px;
    color: var(--maroon-dark);
  }
  .identity .ar{ font-size: 12px; color: var(--green); }
  .identity .contact{
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: .03em;
    color: var(--ink-soft);
    margin-top: 4px;
  }

  .title-block{ text-align:right; }
  .title-block .am{
    display:block;
    font-size: 11px;
    font-weight: 700;
    color: var(--ink-soft);
    margin-bottom: 1px;
  }
  .title-block .en{
    display:block;
    font-family: var(--font-display);
    font-size: 19px;
    font-weight: 700;
    color: var(--maroon);
    white-space: nowrap;
  }
  .meta{
    display:flex;
    gap: 16px;
    justify-content:flex-end;
    margin-top: 8px;
  }
  .meta-item{ display:flex; flex-direction:column; align-items:flex-end; }
  .meta-label{
    font-size: 9.5px;
    text-transform: uppercase;
    letter-spacing: .08em;
    color: var(--ink-soft);
    margin-bottom: 2px;
  }
  .meta-fill{
    min-width: 90px;
    min-height: 18px;
    font-family: var(--font-mono);
    font-size: 13px;
    border-bottom: 1px solid var(--hairline);
    padding: 0 2px 3px;
    text-align:right;
  }
  .meta-fill:focus{ outline: none; border-bottom-color: var(--orange); }
  .stamp-no{
    font-family: var(--font-mono);
    font-size: 19px;
    font-weight: 700;
    color: var(--stamp-red);
    transform: rotate(-3deg);
    display:inline-block;
    padding: 1px 3px;
  }
  .stamp-no:focus{ outline: none; background: rgba(198,173,130,0.25); border-radius: 3px; }

  .rule{
    height: 3px;
    margin: 16px 0 18px;
    background: linear-gradient(90deg, var(--ring-red) 0%, var(--orange) 50%, var(--gold) 100%);
    opacity: 0.85;
    border-radius: 2px;
  }

  /* ---- body: two-column field grid ---- */
  .body-grid{
    display:grid;
    grid-template-columns: 1fr 1fr;
    column-gap: 36px;
    position:relative;
  }
  .body-grid::after{
    content:"";
    position:absolute;
    top:2px; bottom:2px; left:50%;
    width:1px;
    background: var(--hairline);
    opacity:.7;
  }

  .field{ margin-bottom: 14px; }

  .field label{
    display:flex;
    gap: 8px;
    align-items:baseline;
    font-size: 11.5px;
    color: var(--ink-soft);
    margin-bottom: 4px;
  }
  .field label .am{ font-weight: 700; color: var(--ink); font-size: 12px; }
  .field label .en{ font-style: italic; }

  .fill{
    min-height: 20px;
    border-bottom: 1px dotted var(--hairline);
    font-size: 13.5px;
    padding: 0 2px 3px;
  }
  .fill:focus{ outline: none; border-bottom: 1px solid var(--orange); }
  .fill.secondary{ margin-top: 8px; }

  .field.figure label{ justify-content: space-between; }
  .figure-box{
    min-height: 40px;
    background:
      repeating-linear-gradient(135deg, rgba(43,33,24,0.14) 0 2px, transparent 2px 8px),
      var(--paper-light);
    border: 1px solid var(--hairline);
    border-radius: 2px;
    padding: 8px 10px;
    font-family: var(--font-mono);
    font-size: 15px;
    font-weight: 700;
    color: var(--maroon-dark);
  }
  .figure-box:focus{ outline: none; border-color: var(--orange); }

  .sign-block{ margin-top: 4px; }
  .sign-block .fill{ margin-bottom: 5px; }

  .fine-print{
    margin-top: 16px;
    padding-top: 10px;
    border-top: 1px solid var(--hairline);
    font-size: 10px;
    color: var(--ink-soft);
    text-align: center;
    letter-spacing: .02em;
  }

  [contenteditable]{ cursor: text; }

  @media (max-width: 700px){
    .voucher-inner{ padding: 22px 18px 20px 36px; }
    .perforation{ width: 14px; }
    .perforation::before{ left: 4px; }
    header.head{ grid-template-columns: 1fr; justify-items:center; text-align:center; gap: 10px; }
    .title-block{ text-align:center; }
    .meta{ justify-content:center; }
    .meta-item{ align-items:center; }
    .meta-fill{ text-align:center; }
    .body-grid{ grid-template-columns: 1fr; }
    .body-grid::after{ display:none; }
    .title-block .en{ white-space:normal; }
  }

  @media print{
    body{ background: #fff; padding: 0; }
    .toolbar{ display:none; }
    .voucher{ box-shadow:none; max-width: 100%; }
    @page{ size: A5 landscape; margin: 8mm; }
  }
</style>
</head>
<body>

  <div class="toolbar">
    <button onclick="window.print()">Print voucher</button>
  </div>

  <div class="voucher">
    <div class="perforation" aria-hidden="true"></div>
    <div class="voucher-inner">

      <header class="head">
        <div class="brand">
          <div class="badge-wrap">
            <div class="badge">
              <img src="${LOGO}" alt="School Academy logo">
            </div>
          </div>
          <div class="wordmark">
            <span class="iqra">SCHOOL</span>
            <span class="academy">Academy</span>
          </div>
        </div>

        <div class="identity">
          <p class="so">Dugsiga Barbaarinta Caruurta, Hoose, Dhexe &amp; Sare Ee Iqra</p>
          <p class="am">ኢቅራ አፀደሕፃናት አንደኛና ሁለተኛ ደረጃ ት/ቤት</p>
          <p class="en-name">Iqra Kindergarten, Primary, Intermediate and Secondary School</p>
          <p class="ar" dir="rtl">اقرأ روضة الأطفال ومدرسة الإبتدائية والمتوسطة والثانويه</p>
          <p class="contact">Jigjiga, Ethiopia &nbsp;·&nbsp; <strong>Invoice ID: <span data-field="invoice_id">{{invoiceRefCode}}</span></strong></p>
        </div>

        <div class="title-block">
          <span class="am">የገንዘብ መቀበያ ደረሰኝ</span>
          <span class="en">Cash Receipt Voucher</span>
          <div class="meta">
            <div class="meta-item">
              <span class="meta-label">Date</span>
              <span class="meta-fill" contenteditable="true" data-field="date">{{date}}</span>
            </div>
            <div class="meta-item">
              <span class="meta-label">No.</span>
              <span class="stamp-no" contenteditable="true" data-field="voucher_no">{{receiptNumber}}</span>
            </div>
          </div>
        </div>
      </header>

      <div class="rule"></div>

      <div class="body-grid">
        <div class="col">
          <div class="field">
            <label><span class="am">የ</span><span class="en">From</span></label>
            <div class="fill" contenteditable="true" data-field="from">{{from}}</div>
          </div>

          <div class="field">
            <label><span class="am">የተከፈለበት ምክንያት</span><span class="en">Purpose of Payment</span></label>
            <div class="fill" contenteditable="true" data-field="purpose_1">{{purpose}}</div>
            <div class="fill secondary" contenteditable="true" data-field="purpose_2">{{invoiceRef}}</div>
          </div>

          <div class="field">
            <label><span class="am">ቀሪ ክፍያ</span><span class="en">Remainder</span></label>
            <div class="fill" contenteditable="true" data-field="remainder">{{remainder}}</div>
          </div>
        </div>

        <div class="col">
          <div class="field">
            <label><span class="am">በአጻዘ</span><span class="en">Amount in Words</span></label>
            <div class="fill" contenteditable="true" data-field="amount_words">{{amountWords}}</div>
          </div>

          <div class="field figure">
            <label><span class="am">በፊደል</span><span class="en">Payment in Figures</span></label>
            <div class="figure-box" contenteditable="true" data-field="amount_figures">{{amountFigures}}</div>
          </div>

          <div class="field sign-block">
            <div class="fill" contenteditable="true" data-field="cashier">{{cashier}}</div>
            <label><span class="am">የገንዘብ ተቀባይ ስምና ፊርማ</span><span class="en">Cashier's Name &amp; Sign</span></label>
          </div>
        </div>
      </div>

      <div class="fine-print">School Academy &nbsp;•&nbsp; Jigjiga, Ethiopia &nbsp;•&nbsp; <span data-field="invoice_id_print">{{invoiceRefCode}}</span></div>

    </div>
  </div>

</body>
</html>
`;

/**
 * Build the full receipt voucher HTML document with data filled in.
 * @param {Object} data - { date, receiptNumber, from, purpose, invoiceRef, remainder, amountWords, amountFigures, cashier }
 * @returns {string} - Complete HTML document for preview/printing
 */
export function buildReceiptHtml(data = {}) {
  const fill = TEMPLATE
    .replaceAll('{{date}}', data.date || '')
    .replaceAll('{{receiptNumber}}', data.receiptNumber || '')
    .replaceAll('{{from}}', data.from || '')
    .replaceAll('{{purpose}}', data.purpose || '')
    .replaceAll('{{invoiceRef}}', data.invoiceRef || '')
    .replaceAll('{{invoiceRefCode}}', data.invoiceRefCode || '')
    .replaceAll('{{remainder}}', data.remainder || '')
    .replaceAll('{{amountWords}}', data.amountWords || '')
    .replaceAll('{{amountFigures}}', data.amountFigures || '')
    .replaceAll('{{cashier}}', data.cashier || '');
  return fill;
}
